package io.github.rivomesh.platform;

import com.fasterxml.jackson.databind.*;
import com.fasterxml.jackson.databind.node.*;
import io.github.rivomesh.*;
import io.github.rivomesh.cdc.TargetProduct;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.*;
import java.util.concurrent.atomic.AtomicReference;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import static org.junit.jupiter.api.Assertions.*;

class PlatformConfigurationTest {
    @TempDir Path directory;
    final AccessControl.Principal admin=new AccessControl.Principal("editor",PlatformConfig.Role.ADMIN);
    PlatformConfig config(){PlatformConfig c=new PlatformConfig();c.port=0;c.authToken=PlatformTest.TOKEN;c.pollMillis=100;c.tasksDirectory=directory.resolve("tasks").toString();c.dataDirectory=directory.resolve("data").toString();return c;}
    static ObjectNode document(TaskService service,String id)throws Exception{return ((ObjectNode)Model.JSON.valueToTree(service.configuration(id)).get("config")).deepCopy();}
    static Map<String,Object> edit(TaskService service,String id,ObjectNode document,String revision,String request,AccessControl.Principal actor)throws Exception{long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(8);while(true)try{return service.updateConfiguration(id,document,revision,request,actor);}catch(TaskService.Conflict busy){if(!busy.getMessage().equals("TASK_BUSY")||System.nanoTime()>=end)throw busy;Thread.sleep(20);}}
    static Map<String,Object> restore(TaskService service,String id,String reference,String revision,String request,AccessControl.Principal actor)throws Exception{long end=System.nanoTime()+java.util.concurrent.TimeUnit.SECONDS.toNanos(8);while(true)try{return service.restoreConfiguration(id,reference,revision,request,actor);}catch(TaskService.Conflict busy){if(!busy.getMessage().equals("TASK_BUSY")||System.nanoTime()>=end)throw busy;Thread.sleep(20);}}
    @SuppressWarnings("unchecked") static List<Map<String,Object>> versions(TaskService service,String id)throws Exception{return (List<Map<String,Object>>)service.configurationHistory(id,null).get("versions");}
    @Test void redactedEditsAreIdempotentVersionedAndRestoredWithoutResettingIntent()throws Exception{
        PlatformConfig c=config();PlatformTest.Backend backend=new PlatformTest.Backend();PlatformTest.Workers workers=new PlatformTest.Workers();AtomicReference<Config> launched=new AtomicReference<>();String savedVersion,replayRevision;ObjectNode submitted;
        try(TaskService service=new TaskService(c,backend,(path,log,heap)->{launched.set(Config.load(path));return workers.start(path,log,heap);})){
            service.create(Model.JSON.writeValueAsString(PlatformTest.task("sales")),"create_sales",admin);String initial=PlatformTest.revision(service,"sales");submitted=document(service,"sales");String redacted=submitted.toString();for(String secret:Arrays.asList("source-secret","target-secret","url-secret"))assertFalse(redacted.contains(secret));assertTrue(submitted.path("target").path("url").isObject());((ObjectNode)submitted.get("source")).put("password","rotated-source");submitted.put("chunkSize",37);
            edit(service,"sales",submitted,initial,"edit_sales_1",admin);String edited=PlatformTest.revision(service,"sales");assertNotEquals(initial,edited);assertEquals("STOPPED",service.view("sales").get("desired"));edit(service,"sales",submitted,initial,"edit_sales_1",admin);assertEquals(edited,PlatformTest.revision(service,"sales"));assertEquals("REQUEST_IDENTITY_CHANGED",assertThrows(TaskService.Conflict.class,()->edit(service,"sales",submitted,initial,"edit_sales_1",new AccessControl.Principal("another",PlatformConfig.Role.ADMIN))).getMessage());
            ObjectNode stale=submitted.deepCopy();assertEquals("REVISION_CHANGED",assertThrows(TaskService.Conflict.class,()->edit(service,"sales",stale,initial,"stale_edit",admin)).getMessage());backend.initialize("sales");service.command("sales","START",edited,"start_sales",-1);PlatformTest.await(()->launched.get()!=null);assertEquals("rotated-source",launched.get().source.password);assertEquals("target-secret",launched.get().target.password);assertTrue(launched.get().target.url.contains("url-secret"));assertEquals(37,launched.get().chunkSize);
            ObjectNode running=document(service,"sales");assertEquals("CONFIG_STOP_REQUIRED",assertThrows(TaskService.Conflict.class,()->edit(service,"sales",running,PlatformTest.revision(service,"sales"),"running_edit",admin)).getMessage());service.command("sales","STOP",PlatformTest.revision(service,"sales"),"stop_sales",-1);PlatformTest.await(()->workers.active.get()==0&&!PlatformTest.operations(service,"sales").contains("PENDING"));List<Map<String,Object>> history=versions(service,"sales");assertEquals(2,history.size());String original=(String)history.get(1).get("reference");replayRevision=PlatformTest.revision(service,"sales");restore(service,"sales",original,replayRevision,"restore_sales",admin);savedVersion=(String)service.view("sales").get("configurationVersion");assertEquals(3,versions(service,"sales").size());assertEquals("RESTORE_CONFIG",versions(service,"sales").get(0).get("action"));assertEquals("editor",versions(service,"sales").get(0).get("actorId"));
            Files.delete(Paths.get(c.tasksDirectory,"sales.yml"));Files.delete(Paths.get(c.dataDirectory,"worker-configs/sales.yml"));
        }
        try(TaskService restarted=new TaskService(c,backend,(path,log,heap)->{launched.set(Config.load(path));return workers.start(path,log,heap);})){
            assertEquals(savedVersion,restarted.view("sales").get("configurationVersion"));assertTrue(Files.isRegularFile(Paths.get(c.tasksDirectory,"sales.yml")));assertEquals("STOPPED",restarted.view("sales").get("desired"));assertEquals(3,versions(restarted,"sales").size());launched.set(null);restarted.command("sales","START",PlatformTest.revision(restarted,"sales"),"start_restored",-1);PlatformTest.await(()->launched.get()!=null);assertEquals("source-secret",launched.get().source.password);assertEquals(PlatformTest.task("sales").chunkSize,launched.get().chunkSize);
        }
    }
    @Test void semanticAndJournalChangesRequireMigrationAndSecretReferencesCannotMove()throws Exception{
        PlatformConfig c=config();PipelineConfig pipeline=new PipelineConfig();pipeline.pipelineId="multi";pipeline.source.clusterId="cluster";pipeline.source.host="mysql";pipeline.source.username="source";pipeline.source.password="source-hidden";pipeline.databases=Collections.singletonList("sales");PipelineConfig.Target target=new PipelineConfig.Target();target.id="pg";target.product=TargetProduct.POSTGRESQL;target.url="jdbc:postgresql://pg/test";target.username="writer";target.password="target-hidden";target.mappings.put("sales","copy");pipeline.targets.add(target);ObjectNode input=Model.JSON.valueToTree(pipeline);((ObjectNode)input.get("journal")).remove("path");
        try(TaskService service=new TaskService(c,new PlatformTest.Backend(),new PlatformTest.Workers())){
            service.create(input.toString(),"create_multi",admin);ObjectNode edited=document(service,"multi");((ObjectNode)edited.path("targets").get(0).get("mappings")).put("sales","different");String revision=PlatformTest.revision(service,"multi");ObjectNode mappingChange=edited;assertEquals(true,service.previewConfiguration("multi",edited,revision).get("migrationRequired"));assertEquals("CONFIG_MIGRATION_REQUIRED",assertThrows(TaskService.Conflict.class,()->edit(service,"multi",mappingChange,revision,"change_mapping",admin)).getMessage());assertEquals(1,versions(service,"multi").size());
            edited=document(service,"multi");((ObjectNode)edited.get("journal")).put("namespace","fresh_namespace");assertEquals(true,service.previewConfiguration("multi",edited,revision).get("stateStoreChanged"));ObjectNode stateChange=edited;assertEquals("CONFIG_MIGRATION_REQUIRED",assertThrows(TaskService.Conflict.class,()->edit(service,"multi",stateChange,revision,"change_journal",admin)).getMessage());
            edited=document(service,"multi");((ObjectNode)edited.path("targets").get(0)).put("id","other");ObjectNode moved=edited;assertEquals("CONFIG_SECRET_REFERENCE_CHANGED",assertThrows(TaskService.Conflict.class,()->service.previewConfiguration("multi",moved,revision)).getMessage());
        }
    }
    @Test void projectionFailureDoesNotLoseCommittedVersionOrLaunchAStaleConfig()throws Exception{
        PlatformConfig c=config();PlatformTest.Backend backend=new PlatformTest.Backend();PlatformTest.Workers workers=new PlatformTest.Workers();AtomicReference<Config> launched=new AtomicReference<>();Path projection=Paths.get(c.dataDirectory,"worker-configs/sales.yml");String saved;
        try(TaskService service=new TaskService(c,backend,workers)){
            service.create(Model.JSON.writeValueAsString(PlatformTest.task("sales")),"create_projection",admin);Files.delete(projection);Files.createDirectory(projection);ObjectNode edited=document(service,"sales");edited.put("chunkSize",61);edit(service,"sales",edited,PlatformTest.revision(service,"sales"),"edit_projection",admin);saved=(String)service.view("sales").get("configurationVersion");assertEquals(true,service.view("sales").get("configurationProjectionPending"));Files.delete(Paths.get(c.tasksDirectory,"sales.yml"));
        }
        try(TaskService service=new TaskService(c,backend,(path,log,heap)->{assertTrue(path.toString().contains("config-versions"));launched.set(Config.load(path));return workers.start(path,log,heap);})){
            assertEquals(saved,service.view("sales").get("configurationVersion"));service.command("sales","START",PlatformTest.revision(service,"sales"),"start_projection",-1);PlatformTest.await(()->launched.get()!=null);assertEquals(61,launched.get().chunkSize);Files.delete(projection);PlatformTest.await(()->Boolean.FALSE.equals(service.view("sales").get("configurationProjectionPending")));
        }
    }
    @Test void corruptVersionBlocksLaunchAndNeverFallsBackToAnOlderProjection()throws Exception{
        PlatformConfig c=config();PlatformTest.Workers workers=new PlatformTest.Workers();try(TaskService service=new TaskService(c,new PlatformTest.Backend(),workers)){
            service.create(Model.JSON.writeValueAsString(PlatformTest.task("sales")),"create_corrupt",admin);Path stored=Paths.get(c.dataDirectory,"config-versions/sales/"+service.view("sales").get("configurationVersion")+".yml");Files.write(stored,"source: invalid".getBytes(StandardCharsets.UTF_8));service.command("sales","START",PlatformTest.revision(service,"sales"),"start_corrupt",-1);PlatformTest.await(()->"CONFIG_VERSION_CORRUPT".equals(service.view("sales").get("problem")));assertEquals(0,workers.starts.get());}
        try(TaskService restarted=new TaskService(c,new PlatformTest.Backend(),workers)){assertEquals(0,((List<?>)restarted.list().get("tasks")).size());assertTrue(restarted.list().get("invalidConfigs").toString().contains("CONFIG_VERSION_CORRUPT"));assertEquals(0,workers.starts.get());}
    }
    @Test void committedHistoryOutlivesBoundedOperationHistoryAndIgnoresOrphanVersions()throws Exception{
        PlatformConfig c=config();try(TaskService service=new TaskService(c,new PlatformTest.Backend(),new PlatformTest.Workers())){
            service.create(Model.JSON.writeValueAsString(PlatformTest.task("sales")),"create_history",admin);for(int i=0;i<42;i++){ObjectNode next=document(service,"sales");next.put("chunkSize",100+i);edit(service,"sales",next,PlatformTest.revision(service,"sales"),"history_edit_"+i,admin);}Map<String,Object> first=service.configurationHistory("sales",null);assertEquals(20,((List<?>)first.get("versions")).size());Map<String,Object> second=service.configurationHistory("sales",(String)first.get("nextCursor"));assertEquals(20,((List<?>)second.get("versions")).size());Map<String,Object> third=service.configurationHistory("sales",(String)second.get("nextCursor"));assertEquals(3,((List<?>)third.get("versions")).size());assertFalse(third.containsKey("nextCursor"));
            ConfigurationVersions orphanStore=new ConfigurationVersions(Paths.get(c.dataDirectory));ConfigurationVersions.Stored orphan=orphanStore.create("sales",Model.JSON.writeValueAsString(PlatformTest.task("sales")),"EDIT_CONFIG","uncommitted",admin,null,null);String forged=orphan.version.id+((String)first.get("nextCursor")).substring(36);assertEquals("CONFIG_HISTORY_CHANGED",assertThrows(TaskService.Conflict.class,()->service.configurationHistory("sales",forged)).getMessage());assertEquals(20,versions(service,"sales").size());
        }
    }
    @Test void externallyLoadedTasksAcquireAnUnattributedBaselineOnTheirFirstEdit()throws Exception{
        PlatformConfig c=config();PrivateFiles.directory(Paths.get(c.tasksDirectory));Path file=Paths.get(c.tasksDirectory,"external-sales.yml");PrivateFiles.write(file,Model.JSON.writeValueAsBytes(PlatformTest.task("sales")));
        try(TaskService service=new TaskService(c,new PlatformTest.Backend(),new PlatformTest.Workers())){assertTrue(versions(service,"sales").isEmpty());ObjectNode next=document(service,"sales");next.put("chunkSize",45);edit(service,"sales",next,PlatformTest.revision(service,"sales"),"edit_external",admin);List<Map<String,Object>> history=versions(service,"sales");assertEquals(2,history.size());assertEquals("IMPORT_BASELINE",history.get(1).get("action"));assertNull(history.get(1).get("actorId"));}
        try(TaskService restarted=new TaskService(c,new PlatformTest.Backend(),new PlatformTest.Workers())){assertEquals(1,((List<?>)restarted.list().get("tasks")).size());assertTrue(((List<?>)restarted.list().get("invalidConfigs")).isEmpty());assertEquals(2,versions(restarted,"sales").size());assertTrue(Files.exists(file));}
    }
    @Test void aWorkerThatDoesNotStopCannotBeReplacedWithAnEditedConfiguration()throws Exception{
        PlatformConfig c=config();java.util.concurrent.atomic.AtomicBoolean alive=new java.util.concurrent.atomic.AtomicBoolean(true);java.util.concurrent.atomic.AtomicInteger starts=new java.util.concurrent.atomic.AtomicInteger();
        try(TaskService service=new TaskService(c,new PlatformTest.Backend(),(path,log,heap)->{starts.incrementAndGet();return new TaskWorker(){public boolean alive(){return alive.get();}public int exitCode(){return 0;}public void stop(){}};})){
            try{service.create(Model.JSON.writeValueAsString(PlatformTest.task("sales")),"create_stubborn",admin);service.command("sales","START",PlatformTest.revision(service,"sales"),"start_stubborn",-1);PlatformTest.await(()->starts.get()==1);service.command("sales","STOP",PlatformTest.revision(service,"sales"),"stop_stubborn",-1);PlatformTest.await(()->"WORKER_STOP_UNCONFIRMED".equals(service.view("sales").get("problem")));ObjectNode next=document(service,"sales");assertEquals("CONFIG_STOP_REQUIRED",assertThrows(TaskService.Conflict.class,()->edit(service,"sales",next,PlatformTest.revision(service,"sales"),"edit_stubborn",admin)).getMessage());}finally{alive.set(false);}
        }
    }
    static final class HttpResult{final int status;final String text;HttpResult(int status,String text){this.status=status;this.text=text;}}
    static HttpResult request(String base,String path,String method,String token,String body,String id)throws Exception{
        java.net.HttpURLConnection c=(java.net.HttpURLConnection)new java.net.URL(base+path).openConnection();c.setConnectTimeout(2000);c.setReadTimeout(5000);c.setRequestMethod(method);if(token!=null)c.setRequestProperty("Authorization","Bearer "+token);if(id!=null)c.setRequestProperty("X-Request-ID",id);if(body!=null){c.setDoOutput(true);c.setRequestProperty("Content-Type","application/json");byte[] bytes=body.getBytes(StandardCharsets.UTF_8);c.setFixedLengthStreamingMode(bytes.length);try(java.io.OutputStream out=c.getOutputStream()){out.write(bytes);}}try{int status=c.getResponseCode();java.io.InputStream stream=status>=400?c.getErrorStream():c.getInputStream();try(java.io.InputStream input=stream;java.io.ByteArrayOutputStream output=new java.io.ByteArrayOutputStream()){byte[] buffer=new byte[4096];int count;while((count=input.read(buffer))!=-1)output.write(buffer,0,count);return new HttpResult(status,new String(output.toByteArray(),StandardCharsets.UTF_8));}}finally{c.disconnect();}
    }
    @Test void actualHttpRoutesRestrictConfigurationBeforeDecodingAndNeverReturnSavedCredentials()throws Exception{
        PlatformConfig c=config();String reader="reader-private-token-at-least-24",operator="operator-private-token-at-least-24";c.users=Arrays.asList(PlatformTest.user("reader",PlatformConfig.Role.VIEWER,reader),PlatformTest.user("operator",PlatformConfig.Role.OPERATOR,operator));
        try(TaskService service=new TaskService(c,new PlatformTest.Backend(),new PlatformTest.Workers());ConsoleServer server=new ConsoleServer(c,service)){
            service.create(Model.JSON.writeValueAsString(PlatformTest.task("sales")),"create_http_editor",admin);server.start();String base="http://127.0.0.1:"+server.port(),path="/api/tasks/sales/configuration";for(String token:Arrays.asList(reader,operator)){assertEquals(403,request(base,path,"GET",token,null,null).status);assertEquals(403,request(base,path+"/history","GET",token,null,null).status);assertEquals(403,request(base,path,"PUT",token,"not-json","forbidden_edit").status);}
            HttpResult read=request(base,path,"GET",PlatformTest.TOKEN,null,null);assertEquals(200,read.status);for(String secret:Arrays.asList("source-secret","target-secret","url-secret"))assertFalse(read.text.contains(secret));ObjectNode body=Model.JSON.createObjectNode();body.set("config",Model.JSON.readTree(read.text).get("config"));body.put("expectedRevision",Model.JSON.readTree(read.text).path("revision").asText());((ObjectNode)body.get("config")).put("chunkSize",49);assertEquals(200,request(base,path+"/validate","POST",PlatformTest.TOKEN,body.toString(),null).status);HttpResult updated=null;for(int i=0;i<50;i++){updated=request(base,path,"PUT",PlatformTest.TOKEN,body.toString(),"http_edit_config");if(updated.status!=409||!updated.text.contains("TASK_BUSY"))break;Thread.sleep(20);}assertEquals(200,updated.status);assertFalse(updated.text.contains("source-secret"));HttpResult history=request(base,path+"/history","GET",PlatformTest.TOKEN,null,null);assertEquals(2,Model.JSON.readTree(history.text).path("versions").size());assertFalse(history.text.contains("secret"));assertEquals(200,request(base,path,"PUT",PlatformTest.TOKEN,body.toString(),"http_edit_config").status);assertTrue(request(base,"/configuration-editor.js","GET",null,null,null).text.contains("configurationSaved"));
        }
    }

}
